import{_ as o,l as s,o as e,c as l,v as i,p as n,x as t,d,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"virtio","description":"","frontmatter":{"title":"virtio","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/virtio.md","filePath":"cs/virtio.md","lastUpdated":1789023840000}'),h={name:"cs/virtio.md"};function A(p,a,v,_,m,u){const r=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=i('<h1 id="virtio" tabindex="-1">virtio <a class="header-anchor" href="#virtio" aria-label="Permalink to &quot;virtio&quot;">​</a></h1><div class="epigraph"><p>virtio 让客机驱动与宿主后端共享描述符环：客机踢队列，宿主处理真实 I/O，避免逐端口模拟传统设备。</p><footer>—— 据 Russell, virtio: Towards a De-Facto Standard For Virtual I/O Devices, 2008；virtio 规范的教学整理</footer></div><p><a href="/cs/ept-npt">上一课</a>加快了译址。<a href="/cs/trap-and-emulate">陷阱与模拟</a> 若对每个 <code>out</code> 到虚拟磁盘端口都陷入，块 I/O 会毁。<a href="/cs/bio-block">bio</a> 与 <a href="/cs/io-dma">DMA</a> 在宿主侧已能搬页。缺口是<strong>半虚拟化 I/O</strong>：客机知道自己在虚拟机里，使用约定好的环，而不是假装成一台古老的 IDE。操作系统课在此收束；下一课网络从端到端分层开始。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全模拟：客驱动以为有 PCI 网卡，每个寄存器访问陷入 VMM，再模拟。正确但慢。virtio：客机里的 virtio-blk/net 驱动把请求填进共享内存环（GPA 已由 EPT 落到宿主页），一次门铃通知宿主。宿主线程或 vhost 取出，走真 <a href="/cs/blk-mq">blk-mq</a> 或真网卡，完成时中断客机。缺口不是发明以太网帧格式——那是<a href="/cs/layering-e2e">分层与端到端</a>——而是这条队列契约。</p><p><span class="marginnote">现代 virtio 可用 virtiofs、vsock 等。本课以块与网为原型。规范由 OASIS virtio 维护；Russell 2008 是早期陈述。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>发现：虚拟 PCI 设备表明 virtio ID。驱动协商特性，分配环。提交：描述符指向客缓冲（GPA）。宿主翻译成 HPA（EPT 或 IOMMU），执行 I/O。完成：写 used 环，注入中断。与容器的 veth 不同：这里有客内核驱动；容器直接用宿主系统调用。</p>',8)),(e(),n(c,null,{default:t(()=>[E(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20GDRV%5B%22%E5%AE%A2%20virtio%20%E9%A9%B1%E5%8A%A8%22%5D%20--%3E%20RING%5B%22%E5%85%B1%E4%BA%AB%E6%8F%8F%E8%BF%B0%E7%AC%A6%E7%8E%AF%22%5D%0A%20%20RING%20--%3E%20BE%5B%22%E5%AE%BF%E4%B8%BB%E5%90%8E%E7%AB%AF%22%5D%0A%20%20BE%20--%3E%20REAL%5B%22%E7%9C%9F%E5%9D%97%E8%AE%BE%E5%A4%87%E6%88%96%E7%BD%91%E5%8D%A1%22%5D%0A%20%20REAL%20--%3E%20IRQ%5B%22%E5%AE%8C%E6%88%90%E4%B8%AD%E6%96%AD%E5%AE%A2%E6%9C%BA%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>virtio 把 I/O 虚拟化从「指令级模拟」改成「批量共享内存协议」，与 io_uring 的精神相近，对象是客/宿而不是用户/核。它依赖 EPT 让环所在页共享，依赖中断注入让客机调度它的驱动。操作系统课的设备模型到此能接到真实吞吐。跨机器的命名与可靠性不在 virtio 里——<a href="/cs/layering-e2e">分层与端到端</a> 从「两台主机」重新提问。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 SR-IOV 的全部 VF 配置。不把每代 virtio 规范章节当考纲。操作系统主干结束：没有再下一课 OS 对象；网络课假定一台机器已能做 DMA 与队列。</p><p>后课默认：客机 I/O 可经半虚拟化队列到达宿主设备。两台机器之间如何分层与端到端查错，下一课<a href="/cs/layering-e2e">分层与端到端</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>virtio 用共享环做半虚拟化 I/O，减少寄存器陷入。</li><li>宿主后端接已有块层与 DMA；客机仍是完整内核。</li><li>跨主机协议分层是下一课<a href="/cs/layering-e2e">分层与端到端</a>。</li><li>出处：Russell, 2008；OASIS virtio；Tanenbaum <em>MOS</em>。</li></ul>',7))])}const I=o(h,[["render",A]]);export{B as __pageData,I as default};
